
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_bkl1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_bkl1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.501811602987626e+00, -4.423291209895313e+00, -4.313528686348169e+00, -4.162027766408999e+00, -3.956721117472577e+00, -3.685784988801580e+00, -3.341594550803622e+00, -2.926857145678935e+00, -2.457548971771835e+00, -1.937477610991180e+00, -1.304431963104521e+00, -7.589558140363017e-01, -6.202359515091371e-01, -5.418434694192250e-01, -4.291245470893076e-01, -2.965720116734984e-01, -1.472245691284932e-01, -4.503162542940769e-02, -6.029843108763651e-03, -6.741774113089777e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


